import{_ as e,o as t,c as r,a2 as o}from"./chunks/framework.CDU0sSpB.js";const c=JSON.parse('{"title":"Human Takeover and Approval","description":"Hearth Human Executor, approval cards, takeover protocol, human erroneous input, and stage mapping.","frontmatter":{"title":"Human Takeover and Approval","description":"Hearth Human Executor, approval cards, takeover protocol, human erroneous input, and stage mapping.","outline":[2,3]},"headers":[],"relativePath":"en/architecture/human-takeover.md","filePath":"en/architecture/human-takeover.md","lastUpdated":1793706118000}'),n={name:"en/architecture/human-takeover.md"};function i(l,a,s,d,p,h){return t(),r("div",null,[...a[0]||(a[0]=[o('<p class="eyebrow">HUMAN TAKEOVER</p><h1 id="human-takeover-and-approval" tabindex="-1">Human Takeover and Approval <a class="header-anchor" href="#human-takeover-and-approval" aria-label="Permalink to &quot;Human Takeover and Approval&quot;">​</a></h1><p class="lead">Humans are not a patch applied after failure, but first-class participants in the execution system. Approvals, takeovers, and human error must all be designed for.</p><h2 id="human-executor-and-takeover" tabindex="-1">Human Executor and Takeover <a class="header-anchor" href="#human-executor-and-takeover" aria-label="Permalink to &quot;Human Executor and Takeover&quot;">​</a></h2><p>Humans are not a patch applied after failure, but a first-class executor of the system.</p><h3 id="approval-card" tabindex="-1">Approval Card <a class="header-anchor" href="#approval-card" aria-label="Permalink to &quot;Approval Card&quot;">​</a></h3><p>Approvals must let the user decide within ten seconds:</p><ul><li>What is about to be done;</li><li>Which account is used;</li><li>The target recipient/file/repository/calendar/resource;</li><li>The content and attachments;</li><li>Reversibility;</li><li>How failure and compensation work;</li><li>The approval&#39;s validity period and scope.</li></ul><h3 id="takeover-protocol" tabindex="-1">Takeover Protocol <a class="header-anchor" href="#takeover-protocol" aria-label="Permalink to &quot;Takeover Protocol&quot;">​</a></h3><ul><li>Show the current browser/desktop;</li><li>Clearly state what the user needs to do;</li><li>Pause automated input;</li><li>Allow actions, annotations, and supplementary information;</li><li>Record the state before and after takeover;</li><li>Support handing back, narrowing scope, and termination.</li></ul><h3 id="human-error-is-also-input" tabindex="-1">Human Error Is Also Input <a class="header-anchor" href="#human-error-is-also-input" aria-label="Permalink to &quot;Human Error Is Also Input&quot;">​</a></h3><p>User rejections, modifications, revocations, and takeovers are not noise, but important samples for evaluation and skill improvement; however, user corrections must not automatically become higher privileges.</p><h2 id="phase-mapping" tabindex="-1">Phase Mapping <a class="header-anchor" href="#phase-mapping" aria-label="Permalink to &quot;Phase Mapping&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Executor</th><th>First Appearance</th></tr></thead><tbody><tr><td>Codex</td><td>Phase 1, step 1.3</td></tr><tr><td>Native (thin layer)</td><td>Phases 1–2</td></tr><tr><td>Connector</td><td>Phase 2</td></tr><tr><td>Browser</td><td>Phase 2</td></tr><tr><td>Document/Data</td><td>Phase 2</td></tr><tr><td>GUI + Human real-time takeover</td><td>Phase 3</td></tr><tr><td>Mobile takeover entry point</td><td>Phase 4</td></tr></tbody></table><p>Phase 1 first defines the capability matrix and interface conventions, then uses one execution capability to prove the smallest task loop; later phases add the other executors gradually.</p>',15)])])}const m=e(n,[["render",i]]);export{c as __pageData,m as default};
